def format_credit_card_mask(number):
    visible = number[-4:]
    masked_len = len(number) - 4
    masked = '*' * masked_len + visible
    chunks = []
    i = 0
    while i < len(masked):
        chunks.append(masked[i:i + 4])
        i += 4
    return ' '.join(chunks)

def is_palindrome_in_base(n, base):
    digits = []
    x = n
    while x > 0:
        digits.append(x % base)
        x //= base
    return len(digits) <= 1

