def render_template_default(template, values, default):
    result = []
    i = 0
    n = len(template)
    while i < n:
        if template[i] == '{':
            end = template.find('}', i)
            if end != -1:
                key = template[i + 1:end]
                result.append(str(values.get(key, default)))
                i = end + 1
                continue
        result.append(template[i])
        i += 1
    return ''.join(result)

def count_goldbach_pairs(n):
