def sort_by_frequency_desc_then_first_occurrence(nums):
    freq = {}
    first_seen = {}
    for idx, val in enumerate(nums):
        if val not in freq:
            freq[val] = 0
            first_seen[val] = idx
        freq[val] += 1
    distinct = list(freq.keys())
    distinct.sort(key=lambda v: (-freq[v], first_seen[v]))
    return distinct

